          data.narration,
          ...(data.engineResults?.map((r) => `â€¢ ${r.summary}`) ?? []),
          ...(data.narrationWarnings?.length ? [`(DM note: ${data.narrationWarnings[0]})`] : []),
          `Turn ${data.recap.turnNumber} saved.`,
          data.nextHook,
