};

export function visibleNpcsForScene(
  adventureId: string,
  sceneId: string,
  npcs: NPC[],
): NPC[] {
  if (adventureId !== 'skt-nightstone-starter') return npcs;
  const visibleIds = SKT_NIGHTSTONE_VISIBLE_NPCS[sceneId];
  if (!visibleIds) return [];
  const visible = new Set(visibleIds);
  return npcs.filter((npc) => visible.has(npc.id));
}

